/**
 * Where processed image files live. The local disk implementation backs
 * development and single-host deployments; an S3-compatible implementation
 * can replace it by binding a different class to {@link MEDIA_STORAGE}.
 *
 * Names are always generated by the API and match {@link MEDIA_FILE_PATTERN};
 * implementations reject anything else.
 */
export interface MediaStorage {
  put(name: string, data: Buffer): Promise<void>;
  read(name: string): Promise<Buffer | null>;
  remove(name: string): Promise<void>;
}

export const MEDIA_STORAGE = Symbol("MEDIA_STORAGE");

export const MEDIA_FILE_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-(sm|lg|og)\.(webp|jpg)$/;
